use super::*;
fn fixture(first:&str,second:&str)->Value{
    json!({"schemaVersion":1,"fields":[],"records":[{"id":"hero","kind":"character","name":"نور 明","aliases":[],"notes":"Unrelated exact notes","links":[{"kind":"scene","id":first}],"values":{}}],"facts":[{"id":"fact","subjectId":"hero","property":"Home","value":"EXACT مِ 中文 \u{e000} 👩🏽‍🚀","status":"fact","confirmed":true,"observerId":null,"source":"Author source","eventId":"event","untilEventId":null}],"events":[{"id":"event","title":"Original event","notes":"","sceneIds":[first],"laneIds":["main"],"time":{"kind":"fixed","day":1,"label":"Authored"}},{"id":"relative","title":"Relative event","notes":"","sceneIds":[second],"laneIds":["main"],"time":{"kind":"relative","eventId":"event","offsetDays":4}}],"readerReveals":[{"id":"reveal","factId":"fact","eventId":null,"scene":{"kind":"scene","id":first},"position":0,"notes":"Authored reveal"},{"id":"event-reveal","factId":null,"eventId":"event","scene":{"kind":"scene","id":second},"position":1,"notes":"Authored flashback"}],"knowledge":[{"id":"knowledge","characterId":"hero","factId":"fact","stance":"knows","factSnapshot":{"subjectId":"hero","property":"Home","value":"EXACT مِ 中文 \u{e000} 👩🏽‍🚀"},"interpretation":"","source":"Explicit author","scope":{"kind":"scenes","sceneIds":[first]}}],"plotPoints":[{"id":"plot","title":"Authored plot link","notes":"","links":[{"kind":"record","id":"hero"}],"requiresPayoff":false,"scopeClosed":false,"payoffId":null}],"boards":[{"id":"board","name":"Board","cards":[{"id":"card","kind":"record","title":"Hero card","body":"","reference":{"kind":"record","id":"hero"},"x":20,"y":20,"labels":[],"groupId":null},{"id":"other-card","kind":"note","title":"Other card","body":"","reference":null,"x":300,"y":20,"labels":[],"groupId":null}],"edges":[{"id":"edge","fromId":"card","toId":"other-card","kind":"reference","label":"Authored edge","confirmed":false}],"groups":[]}],"lanes":[{"id":"main","name":"Main","kind":"main"}],"constraints":[{"id":"constraint","beforeId":"event","afterId":"relative","minimumDays":2,"strict":false,"confirmed":true,"notes":"Authored time constraint"}],"issues":[{"id":"issue","category":"Continuity","description":"Author issue","importance":"medium","links":[{"kind":"record","id":"hero"}],"evidence":[],"status":"open","resolution":""}]})
}
fn scenes()->Vec<(String,String)>{vec![("first".into(),"First · مِ 中文".into()),("second".into(),"Second".into())]}
#[test]fn fact_preview_lists_only_authored_dependencies_without_mutating_snapshots_or_unrelated_rows(){
    let before=fixture("first","second");let original=before.clone();let mut next=before.clone();next["facts"][0]["value"]=json!("New canon 中文");let proposed=next.clone();let view=preview(&before,&next,&scenes());assert_eq!(view.changes.len(),1);assert!(view.errors.is_empty());for kind in ["Knowledge","Reader reveal","Record","Plot point","Board card","Board edge","Issue","Scene"]{assert!(view.dependencies.iter().any(|d|d.kind==kind),"{kind}");}assert_eq!(next["knowledge"],before["knowledge"]);assert_eq!(before,original);assert_eq!(next,proposed);let text=report(&view,&before,&next);assert!(text.contains("EXACT مِ 中文 \u{e000} 👩🏽‍🚀"));assert!(text.contains("New canon 中文"));assert!(text.contains("snapshot stays unchanged"));
}
#[test]fn occurrence_time_preview_follows_explicit_relative_links_without_rescheduling_any_event(){
    let before=fixture("first","second");let mut next=before.clone();next["events"][0]["time"]["day"]=json!(30);let view=preview(&before,&next,&scenes());for kind in ["Relative event","Fact","Knowledge","Reader reveal","Constraint","Scene"]{assert!(view.dependencies.iter().any(|d|d.kind==kind),"{kind}");}assert_eq!(next["events"][1],before["events"][1]);assert_eq!(next["facts"],before["facts"]);assert_eq!(next["knowledge"],before["knowledge"]);assert!(report(&view,&before,&next).contains("not automatically rescheduled"));
}
#[test]fn deleting_a_retained_fact_with_reveal_or_knowledge_dependents_is_refused(){
    let before=fixture("first","second");let mut next=before.clone();next["facts"]=json!([]);let view=preview(&before,&next,&scenes());assert!(view.errors.iter().any(|e|e.contains("dependencies")));assert!(report(&view,&before,&next).contains("Resolve retained links"));assert_eq!(before["facts"].as_array().unwrap().len(),1);
}
#[test]fn limits_are_reported_and_time_variant_edits_preserve_unknown_retained_fields(){
    let mut before=fixture("first","second");before["readerReveals"]=json!((0..1_000).map(|i|json!({"id":format!("reveal-{i}"),"factId":"fact","eventId":null,"scene":{"kind":"scene","id":"first"},"position":i,"notes":"Authored"})).collect::<Vec<_>>());let mut next=before.clone();next["facts"][0]["value"]=json!("Changed");let view=preview(&before,&next,&scenes());assert!(view.limited);assert!(view.dependencies.len()<=DEPENDENCY_LIMIT);assert!(report(&view,&before,&next).contains("no complete chronology validation"));
    let old=json!({"kind":"relative","eventId":"source","offsetDays":4,"retainedExtension":{"text":"exact مِ 中文"}});let new=merge_time(&old,&json!({"kind":"fixed","day":9,"label":"Authored"}));assert_eq!(new["retainedExtension"],old["retainedExtension"]);assert!(new.get("eventId").is_none());assert_eq!(new["day"],9);
}

fn wait(condition:impl Fn()->bool){let start=std::time::Instant::now();let context=glib::MainContext::default();while !condition(){while context.pending(){context.iteration(false);}assert!(start.elapsed()<Duration::from_secs(20),"Ripple GTK operation timed out");std::thread::sleep(Duration::from_millis(8));}while context.pending(){context.iteration(false);}}
fn rpc(client:&Process,op:&str,args:Value)->Value{let result=Rc::new(RefCell::new(None));let out=result.clone();client.rpc(op,args,move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let value=result.borrow_mut().take().unwrap().unwrap();value}
fn form(a:&Workspace)->Rc<RipplePage>{let widget=a.current_widget().unwrap();a.ripple_pages.borrow().iter().find(|p|p.widget.upcast_ref::<gtk::Widget>()==&widget).unwrap().clone()}
fn open(a:&Rc<Workspace>)->Rc<RipplePage>{a.ripple();wait(||a.ripple_pages.borrow().iter().any(|p|p.loaded.get()&&a.current_widget()==Some(p.widget.clone().upcast())));form(a)}
fn button_named(widget:&impl IsA<gtk::Widget>,caption:&str)->Option<gtk::Button>{if let Ok(button)=widget.as_ref().clone().downcast::<gtk::Button>(){if button.label().as_deref()==Some(caption){return Some(button);}}if let Ok(container)=widget.as_ref().clone().downcast::<gtk::Container>(){for child in container.children(){if let Some(button)=button_named(&child,caption){return Some(button);}}}None}
fn reviewed(p:&RipplePage)->String{p.preview_buffer.text(&p.preview_buffer.start_iter(),&p.preview_buffer.end_iter(),true).unwrap_or_default().into()}
fn save_result(a:&Rc<Workspace>)->Result<(),String>{let result=Rc::new(RefCell::new(None));let out=result.clone();a.save_current(move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some());let value=result.borrow_mut().take().unwrap();value}
pub(crate) fn run(binaries:&Path){
    let directory=tempfile::tempdir().unwrap();let data=directory.path().join("ripple-data");let cache=directory.path().join("ripple-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();let worker=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(worker),&data,true).unwrap();let novel=rpc(&client,"create_novel",json!({"title":"Synthetic ripple"}));let pid=novel["project"]["id"].as_str().unwrap().to_owned();let first=novel["scene"]["id"].as_str().unwrap().to_owned();let cid=novel["scene"]["chapterId"].as_str().unwrap();let second=rpc(&client,"create_scene",json!({"chapterId":cid,"scene":{"schemaVersion":1,"title":"Second","document":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exact writing مِ 中文"}]}]}}}));let second_id=second["id"].as_str().unwrap();let original=fixture(&first,second_id);let saved_plan=rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":original,"parent":null}));let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.open.get()&&p.pending.get()==0));let first_scene=rpc(&a.client,"load_scene",json!({"sceneId":first}));
    let p=open(&a);p.value.set_text("New canon مِ 中文");assert!(p.dirty.get());assert!(save_result(&a).unwrap_err().contains("Apply reviewed"));assert_eq!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),saved_plan);
    p.fact_status.set_active_id(Some("belief"));p.prepare();assert!(p.status.text().contains("Only status fact"));p.fact_status.set_active_id(Some("fact"));p.prepare();assert!(reviewed(&p).contains("Knowledge"));assert!(reviewed(&p).contains("New canon مِ 中文"));assert!(p.apply_button.is_sensitive());button_named(&p.widget,"Cancel preview").unwrap().clicked();assert!(p.dirty.get());p.apply();assert!(p.status.text().contains("Preview this exact proposal"));assert_eq!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),saved_plan);
    p.prepare();p.value.set_text("Edited after preview مِ");p.apply();assert!(p.status.text().contains("Preview this exact proposal"));p.prepare();p.composing.set(true);p.apply();assert!(p.status.text().contains("composition"));p.composing.set(false);p.apply();wait(||!p.saving.get());assert!(!p.dirty.get());let committed=rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));assert_eq!(committed["payload"]["facts"][0]["value"],"Edited after preview مِ");for key in ["records","events","knowledge","readerReveals","issues","boards","constraints"]{assert_eq!(committed["payload"][key],original[key]);}
    p.value.set_text("Stale local proposal");p.prepare();let mut concurrent=committed["payload"].clone();concurrent["records"][0]["notes"]=json!("Another window's exact notes");let newer=rpc(&a.client,"save_project_data",json!({"projectId":pid,"kind":"planning","payload":concurrent,"parent":committed["revisionId"]}));p.apply();wait(||!p.saving.get());assert!(p.dirty.get());assert!(p.status.text().contains("Conflict"));assert_eq!(p.value.text(&p.value.start_iter(),&p.value.end_iter(),true).unwrap(),"Stale local proposal");assert_eq!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),newer);
    p.discard();p.load(&a);wait(||p.loaded.get());p.delete.set_active(true);p.prepare();assert!(!p.apply_button.is_sensitive());assert!(reviewed(&p).contains("Resolve retained links"));assert_eq!(rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"planning"})),newer);p.discard();p.entity.set_active_id(Some("event:event"));p.start.set_text("30");p.prepare();assert!(reviewed(&p).contains("Relative event"));assert!(reviewed(&p).contains("Constraint"));
    a.detach_current();let child=WINDOWS.with(|windows|windows.borrow().last().unwrap().clone());assert!(Rc::ptr_eq(&form(&child),&p));a.close();wait(||WINDOWS.with(|windows|windows.borrow().len())==1);p.apply();wait(||!p.saving.get());assert!(!p.dirty.get());let changed=rpc(&child.client,"load_project_data",json!({"projectId":pid,"kind":"planning"}));assert_eq!(changed["payload"]["events"][0]["time"]["day"],30.0);assert_eq!(changed["payload"]["events"][1],newer["payload"]["events"][1]);assert_eq!(changed["payload"]["knowledge"],original["knowledge"]);assert_eq!(changed["payload"]["records"],newer["payload"]["records"]);assert_eq!(rpc(&child.client,"load_scene",json!({"sceneId":first})),first_scene);assert_eq!(rpc(&child.client,"load_scene",json!({"sceneId":second_id}))["scene"],second["scene"]);child.close();wait(||WINDOWS.with(|windows|windows.borrow().is_empty()));
}
